const raw = $input.first().json.output;
// Remove any ```json fences, in case the model adds them
const cleaned = raw.replace(/```json|```/g, '').trim();
const data = JSON.parse(cleaned);
return [{ json: data }];

const items = $input.all().map(i => JSON.parse(i.json.output.replace(/```json|```/g, '').trim()));

// Identify each result by the fields it contains, not by its position
const tests = items.find(x => 'total_run' in x);
const bugs  = items.find(x => 'open_bugs' in x);
const deps  = items.find(x => 'dependencies' in x);

// Release name and type come from the earlier Code node
const rel = $('Parse Intake').first().json;

// Recompute the arithmetic in code, so we don't trust the model
const total_run = tests.areas.reduce((s, a) => s + a.run, 0);
const total_passed = tests.areas.reduce((s, a) => s + a.passed, 0);
const pass_rate = Math.round((total_passed / total_run) * 1000) / 10;

const POLICY = {
  hotfix: { pass: 95, minRun: null, crit: 0, high: 0, blocked: false, atRisk: false },
  minor:  { pass: 97, minRun: null, crit: 0, high: 2, blocked: true,  atRisk: true  },
  major:  { pass: 98, minRun: 400,  crit: 0, high: 2, blocked: true,  atRisk: true  }
};
const p = POLICY[rel.type];

const openBugs = (bugs?.open_bugs ?? []).filter(b => ['Open', 'In progress'].includes(b.status));
const openCrit = openBugs.filter(b => b.severity === 'Critical');
const openHigh = openBugs.filter(b => b.severity === 'High');
const depList = deps?.dependencies ?? [];
const blocked = depList.filter(d => d.status === 'Blocked');
const atRisk = depList.filter(d => d.status === 'At risk');

const rows = [];
rows.push({ rule: 'Test pass rate', limit: `at least ${p.pass}%`, actual: `${pass_rate}%`, status: pass_rate >= p.pass ? 'MET' : 'BROKEN' });
rows.push(p.minRun
  ? { rule: 'Tests run in total', limit: `at least ${p.minRun}`, actual: `${total_run}`, status: total_run >= p.minRun ? 'MET' : 'BROKEN' }
  : { rule: 'Tests run in total', limit: 'none', actual: `${total_run}`, status: 'MET' });
rows.push({ rule: 'Open Critical bugs', limit: `at most ${p.crit}`, actual: `${openCrit.length}`, status: openCrit.length <= p.crit ? 'MET' : 'BROKEN' });
rows.push({ rule: 'Open High bugs', limit: `at most ${p.high}`, actual: `${openHigh.length}`, status: openHigh.length <= p.high ? 'MET' : 'BROKEN' });
rows.push(p.blocked
  ? { rule: 'Blocked dependencies', limit: 'not allowed (0)', actual: `${blocked.length}`, status: blocked.length === 0 ? 'MET' : 'BROKEN' }
  : { rule: 'Blocked dependencies', limit: 'not checked', actual: 'n/a', status: 'N/A' });

const broken = rows.filter(r => r.status === 'BROKEN');
const conditions = [
  ...openHigh.map(b => `Open High bug ${b.bug_id} - owner ${b.owner}`),
  ...(p.atRisk ? atRisk.map(d => `At risk dependency ${d.dep_id} - ${d.team}`) : [])
];

let verdict = 'GO';
if (broken.length > 0) verdict = 'NO-GO';
else if (conditions.length > 0) verdict = 'GO WITH CONDITIONS';

return [{ json: {
  release_id: rel.release_id, name: rel.name, type: rel.type,
  verdict, rows,
  broken: broken.map(r => `${r.rule}: ${r.actual} (limit: ${r.limit})`),
  conditions: verdict === 'GO WITH CONDITIONS' ? conditions : [],
  open_bugs: openBugs, dependencies: depList
}}];

const raw = $input.first().json.output;
const r = JSON.parse(raw.replace(/```json|```/g, '').trim());
return [{ json: { approved: r.approved, issues: r.issues || [], memo: $('Memo Writer').first().json.output } }];
